import { useEffect, useState } from "react";
import { motion } from "framer-motion";

export default function Testimonials() {
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("http://localhost:5001/admin/reviews")
      .then((res) => res.json())
      .then((data) => {
        const activeReviews = data.filter(r => r.status === "Active");
        setReviews(activeReviews);
      })
      .catch((err) => console.error("Reviews fetch error:", err))
      .finally(() => setLoading(false));
  }, []);

  return (
    <section
      id="testimonials"
      className="bg-black pt-32 pb-28 px-5"
    >
      <div className="max-w-4xl mx-auto">
        {/* HEADER */}
        <motion.h2
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="text-center text-4xl md:text-5xl font-bold text-white mb-4"
        >
          Member <span className="text-[#e9b21a]">Reviews</span>
        </motion.h2>

        <p className="text-center text-gray-400 mb-16">
          Trusted by real people who train with purpose at BodyZeal Fitworks
        </p>

        {/* STATES */}
        {loading && (
          <p className="text-center text-gray-500">
            Loading reviews...
          </p>
        )}

        {!loading && reviews.length === 0 && (
          <p className="text-center text-gray-500">
            No reviews available
          </p>
        )}

        {/* REVIEW LIST */}
        <div className="divide-y divide-white/10">
          {reviews.map((r, i) => (
            <motion.div
              key={r.id}
              initial={{ opacity: 0, y: 25 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.45, delay: i * 0.05 }}
              className="py-10"
            >
              {/* STAR + RATING ROW */}
              <div className="flex items-center gap-3 mb-3">
                <div className="flex text-xl">
                  {Array.from({ length: 5 }).map((_, idx) => (
                    <span
                      key={idx}
                      className={
                        idx < r.rating
                          ? "text-[#e9b21a]"
                          : "text-gray-600"
                      }
                    >
                      ★
                    </span>
                  ))}
                </div>

                <span className="text-sm text-gray-400">
                  {r.rating}.0 / 5
                </span>
              </div>

              {/* MESSAGE */}
              <p className="text-gray-200 text-lg leading-relaxed max-w-3xl">
                {r.message}
              </p>

              {/* FOOTER */}
              <div className="mt-4 text-sm tracking-wide text-[#e9b21a]">
                — {r.name}
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
